const config = $node['Load Config'].json?.data?.attributes || $node['Load Config'].json?.data || {};
const learningsRaw = $node['Fetch AI Learnings'].json?.data;
const learnings = (Array.isArray(learningsRaw) && learningsRaw.length > 0) ? (learningsRaw[0].attributes || learningsRaw[0]).learnings_json || {} : {};
const topContent = ($node['Fetch Top Content'].json?.data || []).map(c => c.attributes || c);
const adCampaigns = $node['Fetch Ad Campaigns'].json?.data || [];

const graphVersion = config.graph_api_version || $env.GRAPH_API_VERSION || 'v21.0';
const adAccountId = config.meta_ad_account_id || $env.META_AD_ACCOUNT_ID || '';
const fbToken = config.facebook_page_access_token || $env.FB_PAGE_ACCESS_TOKEN || '';
const tiktokAdToken = config.tiktok_ads_access_token || $env.TIKTOK_ADS_TOKEN || '';
const tiktokAdvertiserId = config.tiktok_advertiser_id || $env.TIKTOK_ADVERTISER_ID || '';

const campaignScore = learnings.campaign_score || 50;
const bestChannel = learnings.best_channel || 'instagram';
const peakHours = learnings.peak_hours || [12, 19, 20];

// --- Process pending campaigns: create ads ---
const pendingCampaigns = adCampaigns.filter(c => (c.attributes || c).status === 'pending');
const activeCampaigns = adCampaigns.filter(c => (c.attributes || c).status === 'active');

// Auto-select best content for new ads if no image specified
const bestMedia = topContent.length > 0 ? topContent[0] : null;

const toCreate = pendingCampaigns.map(c => {
  const attr = c.attributes || c;
  const budgetMultiplier = campaignScore >= 80 ? 2.0 : campaignScore >= 60 ? 1.5 : 1.0;
  const baseBudget = attr.daily_budget_cents || 500;

  return {
    strapi_id: c.id,
    name: attr.name || `Auto Ad ${new Date().toLocaleDateString('fr-FR')}`,
    objective: attr.objective || 'OUTCOME_ENGAGEMENT',
    daily_budget: Math.round(baseBudget * budgetMultiplier),
    image_url: attr.image_url || (bestMedia ? bestMedia.image_square_url : null),
    video_url: attr.video_url || (bestMedia ? bestMedia.video_url : null),
    ad_text: attr.ad_text || (bestMedia ? bestMedia.caption_a : '🔥 Commandez maintenant!'),
    targeting: {
      geo_locations: { countries: ['DZ'], cities: attr.target_cities ? attr.target_cities.map(c => ({ key: c })) : [] },
      age_min: attr.age_min || 18,
      age_max: attr.age_max || 55,
      publisher_platforms: bestChannel === 'instagram' ? ['instagram', 'facebook'] : ['facebook', 'instagram'],
      interests: attr.interests || [{ id: '6003139266461', name: 'Food & Dining' }]
    },
    platform: 'meta'
  };
});

// --- Check active campaigns for performance ---
const toCheck = activeCampaigns.filter(c => (c.attributes || c).meta_campaign_id).map(c => {
  const attr = c.attributes || c;
  return {
    strapi_id: c.id,
    meta_campaign_id: attr.meta_campaign_id,
    meta_adset_id: attr.meta_adset_id,
    launched_at: attr.launched_at,
    hours_active: (Date.now() - new Date(attr.launched_at).getTime()) / 3600000
  };
});

return [{ json: {
  ad_account_id: adAccountId,
  fb_token: fbToken,
  graph_version: graphVersion,
  tiktok_ad_token: tiktokAdToken,
  tiktok_advertiser_id: tiktokAdvertiserId,
  campaign_score: campaignScore,
  to_create: toCreate,
  to_check: toCheck,
  has_pending: toCreate.length > 0,
  has_active: toCheck.length > 0
}}];

// Process each pending campaign - create on Meta
const strategy = $json;
const results = [];

for (const campaign of strategy.to_create) {
  try {
    // Create campaign
    const campaignRes = await fetch(`https://graph.facebook.com/${strategy.graph_version}/act_${strategy.ad_account_id}/campaigns`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: campaign.name,
        objective: campaign.objective,
        status: 'PAUSED',
        special_ad_categories: ['NONE'],
        access_token: strategy.fb_token
      })
    });
    const campaignData = await campaignRes.json();

    // Create ad set
    let adsetData = {};
    if (campaignData.id) {
      const adsetRes = await fetch(`https://graph.facebook.com/${strategy.graph_version}/act_${strategy.ad_account_id}/adsets`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: campaign.name + ' - AdSet',
          campaign_id: campaignData.id,
          daily_budget: campaign.daily_budget,
          billing_event: 'IMPRESSIONS',
          optimization_goal: 'REACH',
          targeting: campaign.targeting,
          status: 'PAUSED',
          access_token: strategy.fb_token
        })
      });
      adsetData = await adsetRes.json();
    }

    // Create ad creative + ad
    let adData = {};
    if (adsetData.id && (campaign.image_url || campaign.video_url)) {
      const creativeRes = await fetch(`https://graph.facebook.com/${strategy.graph_version}/act_${strategy.ad_account_id}/adcreatives`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: campaign.name + ' - Creative',
          object_story_spec: {
            link_data: {
              message: campaign.ad_text,
              link: campaign.image_url || campaign.video_url,
              image_url: campaign.image_url
            }
          },
          access_token: strategy.fb_token
        })
      });
      const creativeData = await creativeRes.json();

      if (creativeData.id) {
        const adRes = await fetch(`https://graph.facebook.com/${strategy.graph_version}/act_${strategy.ad_account_id}/ads`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            name: campaign.name + ' - Ad',
            adset_id: adsetData.id,
            creative: { creative_id: creativeData.id },
            status: 'PAUSED',
            access_token: strategy.fb_token
          })
        });
        adData = await adRes.json();
      }
    }

    results.push({
      strapi_id: campaign.strapi_id,
      meta_campaign_id: campaignData.id || null,
      meta_adset_id: adsetData.id || null,
      meta_ad_id: adData.id || null,
      budget: campaign.daily_budget,
      success: !!campaignData.id,
      error: campaignData.error?.message || null
    });
  } catch(e) {
    results.push({ strapi_id: campaign.strapi_id, success: false, error: e.message });
  }
}

return [{ json: { ...strategy, creation_results: results } }];

// Pull performance metrics for active campaigns
const strategy = $json;
const metrics = [];

for (const campaign of strategy.to_check) {
  try {
    const res = await fetch(`https://graph.facebook.com/${strategy.graph_version}/${campaign.meta_campaign_id}/insights?fields=impressions,clicks,spend,actions&access_token=${strategy.fb_token}`);
    const data = await res.json();
    const insight = data.data?.[0] || {};

    const impressions = parseInt(insight.impressions || 0);
    const clicks = parseInt(insight.clicks || 0);
    const spend = parseFloat(insight.spend || 0);
    const purchases = (insight.actions || []).find(a => a.action_type === 'purchase')?.value || 0;
    const ctr = impressions > 0 ? ((clicks / impressions) * 100).toFixed(2) : 0;
    const roas = spend > 0 ? (purchases * 1000 / spend).toFixed(2) : 0; // Simplified ROAS

    // Auto-pause if ROAS < 1 after 24h
    const shouldPause = campaign.hours_active > 24 && parseFloat(roas) < 1 && spend > 0;

    if (shouldPause) {
      await fetch(`https://graph.facebook.com/${strategy.graph_version}/${campaign.meta_adset_id}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'PAUSED', access_token: strategy.fb_token })
      });
    }

    metrics.push({
      strapi_id: campaign.strapi_id,
      impressions, clicks, spend, purchases: parseInt(purchases),
      ctr: parseFloat(ctr), roas: parseFloat(roas),
      hours_active: Math.round(campaign.hours_active),
      auto_paused: shouldPause
    });
  } catch(e) {
    metrics.push({ strapi_id: campaign.strapi_id, error: e.message });
  }
}

return [{ json: { ...strategy, performance_metrics: metrics } }];

// Update Strapi with all results
const data = $json;
const updates = [];

// Update created campaigns
for (const result of (data.creation_results || [])) {
  if (result.strapi_id) {
    try {
      await fetch(`${$env.STRAPI_URL || 'http://strapi:1337'}/api/ad-campaigns/${result.strapi_id}`, {
        method: 'PUT',
        headers: { 'Authorization': `Bearer ${$env.STRAPI_API_TOKEN}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ data: {
          status: result.success ? 'active' : 'failed',
          meta_campaign_id: result.meta_campaign_id,
          meta_adset_id: result.meta_adset_id,
          meta_ad_id: result.meta_ad_id,
          actual_budget: result.budget,
          launched_at: result.success ? new Date().toISOString() : null,
          error_message: result.error
        }})
      });
      updates.push({ id: result.strapi_id, action: 'created', success: result.success });
    } catch(e) { updates.push({ id: result.strapi_id, action: 'create_update_failed', error: e.message }); }
  }
}

// Update performance metrics
for (const metric of (data.performance_metrics || [])) {
  if (metric.strapi_id && !metric.error) {
    try {
      await fetch(`${$env.STRAPI_URL || 'http://strapi:1337'}/api/ad-campaigns/${metric.strapi_id}`, {
        method: 'PUT',
        headers: { 'Authorization': `Bearer ${$env.STRAPI_API_TOKEN}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ data: {
          impressions: metric.impressions,
          clicks: metric.clicks,
          spend_cents: Math.round(metric.spend * 100),
          ctr: metric.ctr,
          roas: metric.roas,
          status: metric.auto_paused ? 'paused' : 'active',
          auto_paused: metric.auto_paused,
          last_metrics_pull: new Date().toISOString()
        }})
      });
      updates.push({ id: metric.strapi_id, action: 'metrics_updated', auto_paused: metric.auto_paused });
    } catch(e) { updates.push({ id: metric.strapi_id, action: 'metrics_update_failed', error: e.message }); }
  }
}

// Log to funnel
try {
  await fetch(`${$env.STRAPI_URL || 'http://strapi:1337'}/api/funnel-events`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${$env.STRAPI_API_TOKEN}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ data: {
      event_type: 'ad_management_cycle',
      channel: 'meta_ads',
      session_id: 'ad_mgr_' + Date.now(),
      metadata_json: {
        created: data.creation_results?.length || 0,
        checked: data.performance_metrics?.length || 0,
        auto_paused: (data.performance_metrics || []).filter(m => m.auto_paused).length,
        campaign_score: data.campaign_score
      }
    }})
  });
} catch(e) {}

return [{ json: { updates, total_created: data.creation_results?.length || 0, total_checked: data.performance_metrics?.length || 0 } }];
